import {
  computeColorSchemeRange,
  getNodeColor
} from "./chunk-NP356MC2.js";
import {
  abgrToCssRgba
} from "./chunk-G2FD7S3C.js";

// src/tubeMap/nodeColors.ts
function tubeMapNodeColors(graph, colorScheme, referenceRamp) {
  if (colorScheme === "uniform" || colorScheme === "grey") {
    return void 0;
  }
  const range = { ...computeColorSchemeRange(graph), referenceRamp };
  return new Map(
    graph.nodes.map((node, index) => [
      node.id,
      abgrToCssRgba(getNodeColor(node, index, colorScheme, range))
    ])
  );
}

export {
  tubeMapNodeColors
};
